// The legacy CRM's nightly export. It is regenerated once a day, so customers
// registered since the last export are not in it.
import { readFileSync } from "node:fs";

const EXPORT = new URL("../../data/legacy-crm.json", import.meta.url);

export function readExport() {
  return JSON.parse(readFileSync(EXPORT, "utf8"));
}

export const TIERS = { standard: "standard", gold: "gold", platinum: "platinum" };
```
## src/handlers/customers.register.mjs (read-only; customers.register@1 changes resource:urn:example:customers:customer, which the target reads)
```
import { errors } from "@appport/protocol";
import { findByEmail, nextCustomerId, putCustomer } from "../store.mjs";

export async function registerCustomer(input, context) {
  if (findByEmail(input.email)) {
    throw errors.conflict(`a customer with email ${input.email} already exists`);
  }
  const customer = {
    customerId: nextCustomerId(),
    name: input.name,
    email: input.email,
    tier: input.tier,
    since: new Date().toISOString()
  };
  putCustomer(customer);
  await context.emit({ name: "customers.registered", version: 1, payload: { customerId: customer.customerId, email: customer.email } });
  return customer;
}
```
